function DebugBox_IMGUI_Lua:__init()
    self.controller = nil

    self.vTargetFollow = nil     -- Transform
    self.humanCharacter = nil    -- Character
    self.catCharacter = nil      -- Character
    self.humanMotor = nil        -- KinematicCharacterMotor
    self.catMotor = nil          -- KinematicCharacterMotor
    self.switchablePlayerController = nil    -- lua SwitchablePlayerController

    self.mCamera = nil                  -- Camera
    self.isInit = false
end


function DebugBox_IMGUI_Lua:__delete()
    if self.co_1 ~= nil then
        cs_coroutine.stop(self.co_1)
    end
    self.co_1 = nil
end


function DebugBox_IMGUI_Lua:Start()
    KTool.SetActive(self.controller.gameObject, true);

    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()

    originfFixedDeltaTime = Time.fixedDeltaTime

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end


function DebugBox_IMGUI_Lua:DelayInit()

    coroutine.yield(Yielders.EndOfFrame)
    coroutine.yield(Yielders.EndOfFrame)
    
    for i = 1, DreamSpaceStates.DelayInitWaitFrames do
        self.vTargetFollow = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        self.humanCharacter = GlobalsInDreamSpace.FindComponent("humanCharacter")
        self.catCharacter = GlobalsInDreamSpace.FindComponent("catCharacter")
        self.switchablePlayerControllerBH = GlobalsInDreamSpace.FindComponent("switchablePlayerControllerBH")

        if isNotNull( self.vTargetFollow ) and isNotNull( self.humanCharacter ) and isNotNull( self.catCharacter ) and isNotNull(self.switchablePlayerControllerBH) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end
    
    if isNull( self.vTargetFollow ) or isNull( self.humanCharacter ) or isNull( self.catCharacter )
       or GlobalsInDreamSpace.GetStringState("MorphologyType") == "" 
       or GlobalsInDreamSpace.GetStringState("MorphologyType") == "None" then
        printError("始终没能找到 vTargetFollow or humanCharacter or catCharacter or switchablePlayerControllerBH, 请查找原因")
        return
    end

    self.switchablePlayerController = DreamSpaceLuaUtils.GetLuaScr(self.switchablePlayerControllerBH.gameObject, "Game.DreamSpace.CharacterController.SwitchablePlayerController" )

    assert( self.switchablePlayerController )
    
    self.humanMotor = KTool.GetComponent(self.humanCharacter.gameObject, typeof(KinematicCharacterMotor))
    self.catMotor = KTool.GetComponent(self.catCharacter.gameObject, typeof(KinematicCharacterMotor))
    assert(self.humanMotor ~= nil and self.catMotor ~= nil)


    -- =======
    self.imguiComp = KTool.GetComponent(self.controller.gameObject, typeof(IMGUIComp))
    if isNull(self.imguiComp) then 
        printError("koko - 查找 DebugBoxIMGUI 组件失败")
        return
    end 


    self.humanTF = self.humanCharacter.transform
    self.catTF = self.catCharacter.transform
    self.mCameraTF = self.mCamera.transform

    self.OnMovePanelOpen = function()
        self:_OnMovePanelOpen()
    end
    self.OnMovePanelClose = function()
        self:_OnMovePanelClose()
    end
    self.OnMove = function(moveType_)
        self:_OnMove(moveType_)
    end
    self.OnDestroyBox = function()
        self:_Clear()
    end

    self.imguiComp:OnRestart('+',           self.OnRestart)
    self.imguiComp:OnSetSpeed('+',          self.OnSetSpeed)
    self.imguiComp:OnSetFrame('+',          self.OnSetFrame)

    self.imguiComp:OnMovePanelOpen('+',     self.OnMovePanelOpen)
    self.imguiComp:OnMovePanelClose('+',    self.OnMovePanelClose)
    self.imguiComp:OnMove('+',              self.OnMove)
    self.imguiComp:OnDestroyBox('+',        self.OnDestroyBox)

    self.isInit = true
    print("koko - debugBox 初始化完成")
end



function DebugBox_IMGUI_Lua:OnDestroy()

    if self.isInit == true then

        if self.imguiComp then
            self.imguiComp:OnRestart('-',           self.OnRestart)
            self.imguiComp:OnSetSpeed('-',          self.OnSetSpeed)
            self.imguiComp:OnSetFrame('-',          self.OnSetFrame)

            self.imguiComp:OnMovePanelOpen('-',     self.OnMovePanelOpen)
            self.imguiComp:OnMovePanelClose('-',    self.OnMovePanelClose)
            self.imguiComp:OnMove('-',              self.OnMove)
            self.imguiComp:OnDestroyBox('-',        self.OnDestroyBox)
        end

        self.OnMovePanelOpen = nil 
        self.OnMovePanelClose = nil
        self.OnMove = nil 
        self.OnDestroyBox = nil
    end

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end





