function DebugBox_IMGUI_Lua.OnSetSpeed( newSpeedScale_ )
    assert( type(newSpeedScale_) == "number" )
    Time.timeScale = newSpeedScale_
    Time.fixedDeltaTime = originfFixedDeltaTime * Time.timeScale
    print( "koko - 修改 Speed -> " .. tostring(newSpeedScale_) );
end


function DebugBox_IMGUI_Lua.OnSetFrame( newFPS_ )
    assert( type(newFPS_) == "number" )
    Application.targetFrameRate = newFPS_
    print( "koko - 修改 Frame -> " .. tostring(newFPS_) );
end




function DebugBox_IMGUI_Lua:_OnMovePanelOpen()
    -- Enable functionality
    -- Physics.autoSimulation = false
    self.humanMotor.Capsule.enabled = false
    self.catMotor.Capsule.enabled = false
    self.humanMotor.enabled = false
    self.catMotor.enabled = false

end

function DebugBox_IMGUI_Lua:_OnMovePanelClose()
    -- Disable functionality
    -- Physics.autoSimulation = true
    self.humanMotor.Capsule.enabled = true
    self.catMotor.Capsule.enabled = true
    self.humanMotor.enabled = true
    self.catMotor.enabled = true

end

function DebugBox_IMGUI_Lua:_OnMove( moveType_ )

    if moveType_ == MoveType.Up then 
        self:DoMove(0, moveSpeed * Time.deltaTime, 0)
    elseif moveType_ == MoveType.Down then 
        self:DoMove(0, -moveSpeed * Time.deltaTime, 0)
    elseif moveType_ == MoveType.Left then 
        self:DoMove(-moveSpeed * Time.deltaTime, 0, 0)
    elseif moveType_ == MoveType.Right then 
        self:DoMove(moveSpeed * Time.deltaTime, 0, 0)
    elseif moveType_ == MoveType.Front then 
        self:DoMove(0, 0, moveSpeed * Time.deltaTime)
    elseif moveType_ == MoveType.Back then 
        self:DoMove(0, 0, -moveSpeed * Time.deltaTime)
    else
        printError("koko - 参数异常")
    end
end

function DebugBox_IMGUI_Lua:DoMove(x, y, z)
    local offset = self:GetMoveOffset(x, y, z)
    self.humanTF.position = self.humanTF.position + offset
    self.catTF.position = self.catTF.position + offset
end

function DebugBox_IMGUI_Lua:GetMoveOffset(x, y, z)
    local forward = Vector3.ProjectOnPlane(self.mCameraTF.forward, Vector3.up)
    local up = Vector3.up
    local right = Vector3.Cross(up, forward)
    return right * x + up * y + forward * z
end








return DebugBox_IMGUI_Lua

